package com.schooloss.fullnative.feature.common;
import android.os.Bundle;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import org.json.*;import java.util.*;
public final class EntityDetailActivity extends BaseActivity {
 private String type;private int id;
 @Override protected void onCreate(Bundle b){super.onCreate(b);type=getIntent().getStringExtra("type");id=getIntent().getIntExtra("id",0);loading("Opening record","Loading native SchoolOS detail…");load();}
 private void load(){io.execute(()->{try{JSONObject r=api.get("entity","type="+java.net.URLEncoder.encode(type==null?"record":type,"UTF-8")+"&id="+id);JSONObject d=r.optJSONObject("data");runOnUiThread(()->render(d));}catch(Exception e){runOnUiThread(()->error("Could not open record",e,this::load));}});}
 private void render(JSONObject d){if(d==null)d=new JSONObject();LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,16),Ui.dp(this,14),Ui.dp(this,16),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);TextView back=Ui.text(this,"‹  Back",12,Constants.BLUE,true);back.setOnClickListener(v->finish());p.addView(back);p.addView(Ui.gap(this,8));p.addView(Ui.text(this,d.optString("title",Ui.pretty(type)),24,Constants.TEXT,true));p.addView(Ui.text(this,d.optString("subtitle","SchoolOS record"),11,Constants.MUTED,false));JSONObject f=d.optJSONObject("fields");if(f!=null){Iterator<String> it=f.keys();while(it.hasNext()){String k=it.next();Object val=f.opt(k);com.google.android.material.card.MaterialCardView c=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,13),Ui.dp(this,11),Ui.dp(this,13),Ui.dp(this,11));in.addView(Ui.text(this,Ui.pretty(k),9,Constants.MUTED,true));in.addView(Ui.text(this,val==null||JSONObject.NULL.equals(val)?"—":String.valueOf(val),13,Constants.TEXT,false));c.addView(in);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.topMargin=Ui.dp(this,7);p.addView(c,lp);}}ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);}
}